  "test": "import request from 'supertest';
import { beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app';
import { createDb, type DB } from '../src/db';

let db: DB;
let app: ReturnType<typeof createApp>;

beforeEach(() => {
  db = createDb();
  app = createApp(db);
});

describe('seguridad de autenticación', () => {
  it('rechaza el header x-user-id arbitrario para prevenir suplantación de identidad', async () => {
    const res = await request(app)
      .post('/stores/online/orders')
      .set('x-user-id', '1')
      .send({ items: [{ sku: 'POLO-ALG-M', qty: 1 }] });
    expect(res.status).toBe(401);
  });
});
